INSERT INTO post_comment (
    user_id, post_id, root_id, parent_id, type, content, reply_to_user_id, floor,
    like_count, dislike_count, child_count, path, status,
    deleted, version, created_at, updated_at, created_by, updated_by
) VALUES (
             #{userId}, #{postId}, #{rootId}, #{parentId}, #{type}, #{content}, #{replyToUserId}, #{floor},
             #{likeCount}, #{dislikeCount}, #{childCount}, #{path}, #{status}, #{deleted}, #{version},
             #{createdAt}, #{updatedAt}, #{createdBy}, #{updatedBy}
         )

mapper.update:
UPDATE post_comment
SET like_count = like_count + 1,
    version = #{comment.version} + 1,
    updated_at = #{comment.updatedAt},
    updated_by = #{comment.updatedBy}
WHERE id = #{id}
  AND deleted = 0
  AND version = #{comment.version}

UPDATE post_comment
SET dislike_count = dislike_count + 1,
    version = #{comment.version} + 1,
    updated_at = #{comment.updatedAt},
    updated_by = #{comment.updatedBy}
WHERE id = #{id}
  AND deleted = 0
  AND version = #{comment.version}

UPDATE post_comment
SET child_count = child_count + 1,
    version = #{comment.version} + 1,
    updated_at = #{comment.updatedAt},
    updated_by = #{comment.updatedBy}
WHERE id = #{rootId}
  AND deleted = 0
  AND version = #{comment.version}

UPDATE post_comment
content = #{content}, status = #{status}, root_id = #{rootId}, version = #{version}, updated_at = #{updatedAt}, updated_by = #{updatedBy}
WHERE id = #{id} AND deleted = 0

UPDATE post_comment
SET deleted = 1,
    version = #{version} + 1,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE id = #{id}
  AND deleted = 0
  AND version = #{version}

