SELECT 
FROM post_comment
WHERE root_id = #{rootId}
AND deleted = 0
AND id != #{rootId}
ORDER BY created_at ASC

SELECT COUNT(*)
FROM post_comment
WHERE root_id = #{rootId}
  AND deleted = 0
  AND id != #{rootId}

SELECT 
FROM post_comment
WHERE root_id = #{commentId}
AND deleted = 0
AND id != #{commentId}
ORDER BY created_at ASC
LIMIT #{limit}
